import React, { useState, useEffect } from 'react';
import { taskAPI, budgetAPI, inventoryAPI, shoppingAPI } from '../utils/api';
import { useAuthStore } from '../store/authStore';

interface Task {
  id: number;
  title: string;
  description: string;
  priority: string;
  status: string;
  due_date: string;
  assigned_to: number;
}

interface Budget {
  category: string;
  monthly_limit: number;
  spent_amount: number;
}

interface InventoryItem {
  id: number;
  item_name: string;
  quantity: number;
  min_threshold: number;
}

interface ShoppingList {
  id: number;
  title: string;
  status: string;
  created_at: string;
}

const Dashboard: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [lowStockItems, setLowStockItems] = useState<InventoryItem[]>([]);
  const [recentLists, setRecentLists] = useState<ShoppingList[]>([]);
  const [loading, setLoading] = useState(true);
  const { userId } = useAuthStore();

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      const [tasksRes, budgetRes, inventoryRes, shoppingRes] = await Promise.all([
        taskAPI.getAll({ limit: 5 }),
        budgetAPI.get(),
        inventoryAPI.getLowStock(),
        shoppingAPI.getAll()
      ]);
      setTasks(tasksRes.data);
      setBudgets(budgetRes.data);
      setLowStockItems(inventoryRes.data);
      setRecentLists(shoppingRes.data.slice(0, 3));
    } catch (error) {
      console.error('Error loading dashboard:', error);
    } finally {
      setLoading(false);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return '#ff4757';
      case 'medium': return '#ffa502';
      case 'low': return '#2ed573';
      default: return '#747d8c';
    }
  };

  if (loading) {
    return (
      <div style={styles.loading}>
        <div style={styles.spinner}></div>
        <p>Yükleniyor...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>Aile Panosu</h1>
        <p style={styles.subtitle}>Günlük görevler ve bütçe durumu</p>
      </header>

      <div style={styles.grid}>
        {/* Recent Tasks */}
        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle}>📋 Son Görevler</h2>
            <a href="/tasks" style={styles.viewAllLink}>Tümünü Gör</a>
          </div>
          {tasks.length === 0 ? (
            <p style={styles.emptyState}>Henüz görev yok</p>
          ) : (
            <div style={styles.taskList}>
              {tasks.slice(0, 4).map((task) => (
                <div key={task.id} style={styles.taskItem}>
                  <div style={styles.taskHeader}>
                    <h3 style={styles.taskTitle}>{task.title}</h3>
                    <span 
                      style={{
                        ...styles.priorityBadge,
                        backgroundColor: getPriorityColor(task.priority)
                      }}
                    >
                      {task.priority}
                    </span>
                  </div>
                  <p style={styles.taskDesc}>{task.description}</p>
                  <div style={styles.taskMeta}>
                    <span style={styles.taskStatus}>
                      {task.status === 'pending' ? '⏳ Bekliyor' : 
                       task.status === 'in_progress' ? '🔄 Devam Ediyor' : '✅ Tamamlandı'}
                    </span>
                    {task.due_date && (
                      <span style={styles.taskDate}>
                        📅 {new Date(task.due_date).toLocaleDateString('tr-TR')}
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Budget Overview */}
        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle}>💰 Bütçe Durumu</h2>
            <a href="/budget" style={styles.viewAllLink}>Detay</a>
          </div>
          {budgets.length === 0 ? (
            <p style={styles.emptyState}>Bütçe bilgisi yok</p>
          ) : (
            <div style={styles.budgetList}>
              {budgets.slice(0, 4).map((budget, index) => {
                const percentage = (budget.spent_amount / budget.monthly_limit) * 100;
                const categoryNames: { [key: string]: string } = {
                  food: '🍎 Gıda',
                  transport: '🚗 Ulaşım',
                  utilities: '💡 Faturalar',
                  entertainment: '🎬 Eğlence',
                  shopping: '🛒 Alışveriş'
                };
                return (
                  <div key={index} style={styles.budgetItem}>
                    <div style={styles.budgetHeader}>
                      <span style={styles.budgetCategory}>
                        {categoryNames[budget.category] || budget.category}
                      </span>
                      <span style={styles.budgetAmount}>
                        ₺{budget.spent_amount.toLocaleString('tr-TR')} / ₺{budget.monthly_limit.toLocaleString('tr-TR')}
                      </span>
                    </div>
                    <div style={styles.progressBar}>
                      <div 
                        style={{
                          ...styles.progressFill,
                          width: `${Math.min(percentage, 100)}%`,
                          backgroundColor: percentage > 90 ? '#ff4757' : percentage > 70 ? '#ffa502' : '#2ed573'
                        }}
                      ></div>
                    </div>
                    <span style={styles.budgetPercentage}>{percentage.toFixed(1)}%</span>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Low Stock Alert */}
        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle}>⚠️ Düşük Stok Uyarısı</h2>
            <a href="/inventory" style={styles.viewAllLink}>Envanter</a>
          </div>
          {lowStockItems.length === 0 ? (
            <div style={styles.successState}>
              <span style={styles.successIcon}>✅</span>
              <p>Tüm ürünler yeterli stokta!</p>
            </div>
          ) : (
            <div style={styles.alertList}>
              {lowStockItems.slice(0, 5).map((item) => (
                <div key={item.id} style={styles.alertItem}>
                  <div style={styles.alertIcon}>📦</div>
                  <div style={styles.alertContent}>
                    <div style={styles.alertTitle}>{item.item_name}</div>
                    <div style={styles.alertDesc}>
                      Kalan: {item.quantity} | Min: {item.min_threshold}
                    </div>
                  </div>
                  <div style={styles.alertBadge}>Düşük</div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Recent Shopping Lists */}
        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle}>🛒 Son Alışveriş Listeleri</h2>
            <a href="/shopping" style={styles.viewAllLink}>Tümü</a>
          </div>
          {recentLists.length === 0 ? (
            <p style={styles.emptyState}>Henüz alışveriş listesi yok</p>
          ) : (
            <div style={styles.shoppingList}>
              {recentLists.map((list) => (
                <div key={list.id} style={styles.shoppingItem}>
                  <div style={styles.shoppingHeader}>
                    <h3 style={styles.shoppingTitle}>{list.title}</h3>
                    <span style={{
                      ...styles.statusBadge,
                      backgroundColor: list.status === 'completed' ? '#28a745' : 
                                     list.status === 'sent' ? '#007bff' : '#6c757d'
                    }}>
                      {list.status === 'completed' ? 'Tamamlandı' : 
                       list.status === 'sent' ? 'Gönderildi' : 'Taslak'}
                    </span>
                  </div>
                  <div style={styles.shoppingDate}>
                    📅 {new Date(list.created_at).toLocaleDateString('tr-TR')}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Quick Stats */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>📊 Hızlı İstatistikler</h2>
          <div style={styles.statsGrid}>
            <div style={styles.statItem}>
              <div style={styles.statIcon}>⏳</div>
              <div style={styles.statNumber}>{tasks.filter(t => t.status === 'pending').length}</div>
              <div style={styles.statLabel}>Bekleyen Görevler</div>
            </div>
            <div style={styles.statItem}>
              <div style={styles.statIcon}>✅</div>
              <div style={styles.statNumber}>{tasks.filter(t => t.status === 'completed').length}</div>
              <div style={styles.statLabel}>Tamamlanan</div>
            </div>
            <div style={styles.statItem}>
              <div style={styles.statIcon}>👤</div>
              <div style={styles.statNumber}>{tasks.filter(t => t.assigned_to === userId).length}</div>
              <div style={styles.statLabel}>Benim Görevlerim</div>
            </div>
            <div style={styles.statItem}>
              <div style={styles.statIcon}>⚠️</div>
              <div style={styles.statNumber}>{lowStockItems.length}</div>
              <div style={styles.statLabel}>Düşük Stok</div>
            </div>
            <div style={styles.statItem}>
              <div style={styles.statIcon}>💰</div>
              <div style={styles.statNumber}>
                ₺{budgets.reduce((sum, b) => sum + b.spent_amount, 0).toLocaleString('tr-TR')}
              </div>
              <div style={styles.statLabel}>Toplam Harcama</div>
            </div>
            <div style={styles.statItem}>
              <div style={styles.statIcon}>🛒</div>
              <div style={styles.statNumber}>{recentLists.length}</div>
              <div style={styles.statLabel}>Aktif Listeler</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  loading: {
    display: 'flex',
    flexDirection: 'column' as const,
